#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <mma.h>
namespace {
using namespace nvcuda;
constexpr int IN_C = 3;
constexpr int OUT_C = 32;
constexpr int K = 3;
constexpr int K_ELEMS = IN_C * K * K;  // 27
constexpr int K_PAD = 32;             // reduction padded to multiple of 16
constexpr int NTILE = 128;            // output spatial positions per block
constexpr int B_LD = NTILE + 8;       // padded smem B row stride (skew), multiple of 8 elems (16B) to keep WMMA alignment while breaking 256B row-stride bank conflicts
constexpr int THREADS = 256;
constexpr int WM = 16;
constexpr int WN = 16;
constexpr int WK = 16;
constexpr int SMEM_BYTES = OUT_C * NTILE * (int)sizeof(float);  // 16 KB
// Implicit-GEMM 3x3 convolution using bf16 tensor-core WMMA.
// GEMM view: C[oc][s] = sum_k W[oc][k] * im2col(X)[k][s],
//   M = 32 output channels, N = Ho*Wo spatial per image, K = 27 (padded to 32).
__global__ void conv3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo) {
  extern __shared__ __align__(16) unsigned char smem_raw[];
  __nv_bfloat16* sA = reinterpret_cast<__nv_bfloat16*>(smem_raw);  // [32][32]
  __nv_bfloat16* sB = reinterpret_cast<__nv_bfloat16*>(
      smem_raw + OUT_C * K_PAD * sizeof(__nv_bfloat16));           // [32][NTILE]
  float* sC = reinterpret_cast<float*>(smem_raw);                  // reused, [32][NTILE]
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int s0 = blockIdx.x * NTILE;
  const int S = Ho * Wo;
  // Cooperative staging: all 256 threads participate in the global->shared
  // staging phase instead of leaving half the block idle. Each thread owns
  // one spatial column (tid & 127) and one ky-group (tid >> 7): group 0
  // stages the ky=0 im2col rows plus the K_PAD zero fill, group 1 stages
  // the ky=1,2 rows. Weight staging (matrix A) is folded into group 0 so
  // it overlaps with group 1's im2col loads rather than serializing ahead
  // of the B staging, shortening the staging critical path before the MMA.
  {
    const int sl = tid & (NTILE - 1);
    const int kg = tid >> 7;  // ky-group: 0 -> ky=0, 1 -> ky=1..2
    const int s = s0 + sl;
    const bool s_valid = (s < S);
    int oh = 0;
    int ow = 0;
    if (s_valid) {
      oh = s / Wo;
      ow = s - oh * Wo;
    }
    const __nv_bfloat16* xn = x + (size_t)n * IN_C * H * W;
    if (kg == 0) {
      #pragma unroll
      for (int c = 0; c < IN_C; ++c) {
        const int ih = oh;
        #pragma unroll
        for (int kx = 0; kx < K; ++kx) {
          __nv_bfloat16 v = __float2bfloat16(0.0f);
          if (s_valid) {
            v = __ldg(&xn[((size_t)c * H + ih) * W + (ow + kx)]);
          }
          sB[(c * 9 + kx) * B_LD + sl] = v;
        }
      }
      #pragma unroll
      for (int k = K_ELEMS; k < K_PAD; ++k) {
        sB[k * B_LD + sl] = __float2bfloat16(0.0f);
      }
      // Stage weights [32][27] into padded [32][32] shared tile (matrix A).
      #pragma unroll
      for (int j = 0; j < 8; ++j) {
        const int idx = j * 128 + sl;
        const int oc = idx >> 5;
        const int k = idx & 31;
        __nv_bfloat16 v = __float2bfloat16(0.0f);
        if (k < K_ELEMS) {
          v = __ldg(&w[(size_t)oc * K_ELEMS + k]);
        }
        sA[idx] = v;
      }
    } else {
      #pragma unroll
      for (int c = 0; c < IN_C; ++c) {
        #pragma unroll
        for (int ky = 1; ky < K; ++ky) {
          const int ih = oh + ky;
          #pragma unroll
          for (int kx = 0; kx < K; ++kx) {
            __nv_bfloat16 v = __float2bfloat16(0.0f);
            if (s_valid) {
              v = __ldg(&xn[((size_t)c * H + ih) * W + (ow + kx)]);
            }
            sB[(c * 9 + ky * 3 + kx) * B_LD + sl] = v;
          }
        }
      }
    }
  }
  __syncthreads();
  // 8 warps: 2 rows of 16 output channels x 4 slabs of 32 spatial positions.
  const int warp = tid >> 5;
  const int warp_m = warp & 1;
  const int warp_n = warp >> 1;
  const int oc0 = warp_m * WM;
  const int sn0 = warp_n * 32;
  wmma::fragment<wmma::accumulator, WM, WN, WK, float> acc[2];
  #pragma unroll
  for (int i = 0; i < 2; ++i) {
    wmma::fill_fragment(acc[i], 0.0f);
  }
  #pragma unroll
  for (int kt = 0; kt < K_PAD / WK; ++kt) {
    wmma::fragment<wmma::matrix_a, WM, WN, WK, __nv_bfloat16, wmma::row_major> afrag;
    wmma::load_matrix_sync(afrag, sA + oc0 * K_PAD + kt * WK, K_PAD);
    #pragma unroll
    for (int nf = 0; nf < 2; ++nf) {
      wmma::fragment<wmma::matrix_b, WM, WN, WK, __nv_bfloat16, wmma::row_major> bfrag;
      wmma::load_matrix_sync(bfrag, sB + (kt * WK) * B_LD + sn0 + nf * WN, B_LD);
      wmma::mma_sync(acc[nf], afrag, bfrag, acc[nf]);
    }
  }
  __syncthreads();
  // Stage accumulators (f32) into shared memory, reusing the A/B buffer.
  #pragma unroll
  for (int nf = 0; nf < 2; ++nf) {
    wmma::store_matrix_sync(sC + oc0 * NTILE + sn0 + nf * WN, acc[nf], NTILE,
                            wmma::mem_row_major);
  }
  __syncthreads();
  // Convert to bf16 and write out. Each thread packs two adjacent spatial
  // positions into one 32-bit streaming store (st.global.cs): warp stores
  // are 128-byte coalesced and marked evict-first so the large output
  // tensor does not thrash the much smaller input tensor in L2, reducing
  // total DRAM traffic for this DRAM-bound kernel.
  {
    const int half = tid >> 7;            // 0 -> oc 0..15, 1 -> oc 16..31
    const int pair = tid & 63;            // spatial pair index (0..63)
    const int grp = (tid >> 6) & 1;       // 0 -> oc +0..7, 1 -> oc +8..15
    const int sp = s0 + 2 * pair;         // first spatial position of the pair
    if (((S & 1) == 0) && (sp + 1 < S)) {
      // S even: every packed address is 4-byte aligned; all pairs full.
      __nv_bfloat16* yn = y + (size_t)n * OUT_C * S + sp;
      const float2* sCp = reinterpret_cast<const float2*>(sC + 2 * pair);
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const int oc = half * 16 + grp * 8 + i;
        const float2 f2 = sCp[oc * (NTILE / 2)];
        const __nv_bfloat16 b0 = __float2bfloat16(f2.x);
        const __nv_bfloat16 b1 = __float2bfloat16(f2.y);
        const unsigned int packed =
            ((unsigned int)*reinterpret_cast<const unsigned short*>(&b1) << 16) |
            (unsigned int)*reinterpret_cast<const unsigned short*>(&b0);
        __stcs(reinterpret_cast<unsigned int*>(yn + (size_t)oc * S), packed);
      }
    } else if (sp < S) {
      // Odd-S fallback / ragged tail: scalar 16-bit streaming stores.
      __nv_bfloat16* yn = y + (size_t)n * OUT_C * S + sp;
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const int oc = half * 16 + grp * 8 + i;
        const __nv_bfloat16 b0 = __float2bfloat16(sC[oc * NTILE + 2 * pair]);
        __stcs(reinterpret_cast<unsigned short*>(yn + (size_t)oc * S),
               *reinterpret_cast<const unsigned short*>(&b0));
        if (sp + 1 < S) {
          const __nv_bfloat16 b1 = __float2bfloat16(sC[oc * NTILE + 2 * pair + 1]);
          __stcs(reinterpret_cast<unsigned short*>(yn + (size_t)oc * S + 1),
                 *reinterpret_cast<const unsigned short*>(&b1));
        }
      }
    }
  }
}
